_DEFAULT_SCHEMA_NAME_GENERIC = "auto_generated"
_DEFAULT_SCHEMA_FILE = "generated_schema.toml"


def _config_dir() -> Path:
    return default_config_path().parent


def _default_schema_path() -> Path:
    return _config_dir() / _DEFAULT_SCHEMA_FILE


def default_schema_name_for_source(
    has_taxonomy: bool,
    has_tasks: bool,
) -> str:
    """Return a source-aware default schema name.

    Centralised so the CLI wizard and the runtime preview tool agree.
    """
    if has_taxonomy and has_tasks:
        return "auto_generated_from_taxonomy_and_tasks"
    if has_taxonomy:
        return "auto_generated_from_taxonomy"
    if has_tasks:
        return "auto_generated_from_tasks"
    return _DEFAULT_SCHEMA_NAME_GENERIC


# ---------------------------------------------------------------------------
# Taxonomy detection / resolution (single implementation)
# ---------------------------------------------------------------------------


def _candidate_taxonomy_paths(project_dir: str | None = None) -> list[Path]:
    """Return likely taxonomy locations, ordered from project-local to user-global."""
    candidates: list[Path] = []

    if project_dir:
        root = Path(project_dir).expanduser()
        candidates.extend(
            [
                root / "user" / "TAXONOMY.md",
                root / "TAXONOMY.md",
                root / "docs" / "TAXONOMY.md",
                root / "taxonomy.md",
            ]
        )

    cwd = Path.cwd()
    candidates.extend(
        [
            cwd / "user" / "TAXONOMY.md",
            cwd / "TAXONOMY.md",
            cwd / "docs" / "TAXONOMY.md",
            cwd / "taxonomy.md",
            _config_dir() / "TAXONOMY.md",
            _config_dir() / "taxonomy.md",
            Path.home() / "TAXONOMY.md",
        ]
    )

    seen: set[Path] = set()
    unique: list[Path] = []
    for path in candidates:
        expanded = path.expanduser()
        if expanded not in seen:
            seen.add(expanded)
            unique.append(expanded)
    return unique


def detect_taxonomy_files(project_dir: str | None = None) -> list[str]:
    """Find taxonomy files in common locations."""
    return [str(path.resolve()) for path in _candidate_taxonomy_paths(project_dir) if path.exists()]


def resolve_taxonomy_path(
    config: ServerConfig,
    taxonomy_path: str | None = None,
    project_dir: str | None = None,
) -> Path | None:
    """Resolve an explicit, configured, or auto-detected taxonomy path.

    Returns None if the resolved path does not exist.
    """
    if taxonomy_path:
        path = Path(taxonomy_path).expanduser().resolve()
        return path if path.exists() else None
    if config.taxonomy_path:
        path = Path(config.taxonomy_path).expanduser().resolve()
        return path if path.exists() else None
    detected = detect_taxonomy_files(project_dir)
    return Path(detected[0]) if detected else None


