def analyze_existing_tasks(task_cli: TaskwarriorCLI) -> dict[str, Any]:
    """Analyse existing tasks and return field/value statistics for schema design."""
    tasks, error = _safe_export_tasks(task_cli)
    if error:
        return {"error": True, "message": f"Could not export tasks: {error}", "task_count": 0}

    analysis = analyze_tasks(tasks)
    fields: dict[str, Any] = {}
    for name, field in sorted(analysis.fields.items()):
        fields[name] = {
            "occurrence_count": field.occurrence_count,
            "usage_ratio": round(field.usage_ratio, 4),
            "is_uda": field.is_uda,
            "inferred_type": field.inferred_type,
            "inferred_required": field.inferred_required,
            "inferred_values": field.inferred_values,
            "sample_values": field.sample_values,
        }

    return {
        "success": True,
        "task_count": analysis.total_tasks,
        "fields": fields,
        "uda_fields": sorted(analysis.uda_fields().keys()),
        "builtin_fields": sorted(analysis.builtin_fields().keys()),
        "projects": analysis.projects,
        "tags": analysis.tags,
    }


def analyze_taxonomy_file(path: str) -> dict[str, Any]:
    """Parse a taxonomy Markdown file and return extracted semantics."""
    taxonomy_path = Path(path).expanduser().resolve()
    if not taxonomy_path.exists():
        return {"error": True, "message": f"Taxonomy file not found: {taxonomy_path}"}

    taxonomy = parse_taxonomy(taxonomy_path)
    return _taxonomy_summary(taxonomy, taxonomy_path)


def _taxonomy_summary(taxonomy: TaxonomyInfo, taxonomy_path: Path) -> dict[str, Any]:
    return {
        "success": True,
        "taxonomy_path": str(taxonomy_path),
        "field_count": len(taxonomy.fields),
        "condition_count": len(taxonomy.conditions),
        "phase_transition_count": len(taxonomy.phase_transitions),
        "fields": {
            name: {
                "description": field.description,
                "allowed_values": field.allowed_values,
                "type": field.type,
                "required": field.required,
                "uda": field.uda,
                "conditions": field.conditions,
            }
            for name, field in sorted(taxonomy.fields.items())
        },
        "conditions": [
            {
                "name": cond.name,
                "when": cond.when,
                "then_required": cond.then_required,
                "description": cond.description,
            }
            for cond in taxonomy.conditions
        ],
        "phase_transitions": [
            {
                "from_phase": transition.from_phase,
                "to_phase": transition.to_phase,
                "add_fields": transition.add_fields,
                "description": transition.description,
            }
            for transition in taxonomy.phase_transitions
        ],
    }


# ---------------------------------------------------------------------------
# Preview + save (generated schema path)
