def _build_preview_payload(
    *,
    schema_toml: str,
    schema_name: str,
    tasks: list[dict[str, Any]],
    task_error: str | None,
    resolved_taxonomy: Path | None,
) -> dict[str, Any]:
    analysis = analyze_tasks(tasks) if tasks else None
    taxonomy = parse_taxonomy(resolved_taxonomy) if resolved_taxonomy else None

    return {
        "success": True,
        "mutated": False,
        "schema_name": schema_name,
        "task_count": len(tasks),
        "task_export_error": task_error,
        "taxonomy_path": str(resolved_taxonomy) if resolved_taxonomy else None,
        "summary": {
            "fields_from_tasks": sorted(analysis.fields.keys()) if analysis else [],
            "uda_fields_from_tasks": sorted(analysis.uda_fields().keys()) if analysis else [],
            "fields_from_taxonomy": sorted(taxonomy.fields.keys()) if taxonomy else [],
            "conditions_from_taxonomy": len(taxonomy.conditions) if taxonomy else 0,
            "phase_transitions_from_taxonomy": len(taxonomy.phase_transitions) if taxonomy else 0,
        },
        "schema_toml": schema_toml,
        "review_note": (
            "Review schema_toml before saving. Inferred enum/required fields are heuristics; "
            "taxonomy descriptions are treated as higher authority than raw task data."
        ),
    }


def generate_schema_preview(
    config: ServerConfig,
    task_cli: TaskwarriorCLI,
    taxonomy_path: str | None = None,
    project_dir: str | None = None,
    schema_name: str | None = None,
) -> dict[str, Any]:
    """Generate a non-mutating schema preview from tasks, taxonomy, or both.

    If ``schema_name`` is empty/None, a source-aware default is chosen via
    :func:`default_schema_name_for_source`.
    """
    tasks, task_error = _safe_export_tasks(task_cli)
    resolved_taxonomy = resolve_taxonomy_path(config, taxonomy_path, project_dir)

    if resolved_taxonomy and not resolved_taxonomy.exists():
        return {"error": True, "message": f"Taxonomy file not found: {resolved_taxonomy}"}

    if not tasks and not resolved_taxonomy:
        return {
            "error": True,
            "message": "Cannot generate schema preview: no exported tasks and no taxonomy file.",
            "task_export_error": task_error,
        }

    effective_name = (
        schema_name
        if schema_name
        else default_schema_name_for_source(
            has_taxonomy=resolved_taxonomy is not None,
            has_tasks=bool(tasks),
        )
    )

    description = f"Auto-generated from {len(tasks)} tasks"
    if resolved_taxonomy:
        description += f" + {resolved_taxonomy.name}"

    toml_content = generate_schema_from_tasks_and_taxonomy(
        tasks=tasks,
        taxonomy_path=str(resolved_taxonomy) if resolved_taxonomy else None,
        name=effective_name,
        description=description,
    )

    return _build_preview_payload(
        schema_toml=toml_content,
        schema_name=effective_name,
        tasks=tasks,
        task_error=task_error,
        resolved_taxonomy=resolved_taxonomy,
    )


def save_initial_schema(
    schema_toml: str,
    taxonomy_path: str | None = None,
    output_path: str | None = None,
    role: str | None = None,
    overwrite: bool = False,
    update_config: bool = True,
) -> dict[str, Any]:
    """Persist an approved generated schema and optionally update ``config.toml``.

    ``role`` is validated against :class:`Role`.  When ``update_config`` is
    True and no ``role`` is provided, the persisted config defaults to
    ``CONTRIBUTOR`` so that ``ServerConfig.explicit_role_configured`` becomes
    True on the next load and the server leaves onboarding mode.  Pass an
    explicit role (e.g. ``"GENERATOR"`` or ``"MANAGER"``) to grant a higher
    permission level.
    """
    if not schema_toml.strip():
        return {
            "error": True,
            "message": "schema_toml is empty; generate and review a preview first.",
        }

    effective_role: str | None = None
    if update_config:
        candidate = role if role else Role.CONTRIBUTOR
        try:
            effective_role = Role.validate(candidate)
        except ValueError as exc:
            return {"error": True, "message": str(exc)}

    out = Path(output_path).expanduser() if output_path else _default_schema_path()
    if out.exists():
        if not overwrite:
            return {
                "error": True,
                "message": f"Schema file already exists: {out}. Pass overwrite=true to replace it.",
            }
        # Handle race condition: file might be created between check and unlink
        try:
            out.unlink()
        except FileNotFoundError:
            # File was deleted by another process, proceed with save
            pass

    saved_path = save_generated_schema(schema_toml, out)

    cfg_path: Path | None = None
    if update_config:
        cfg_path = upsert_server_config(
            schema_path=str(saved_path),
            taxonomy_path=str(Path(taxonomy_path).expanduser().resolve())
            if taxonomy_path
            else None,
            role=effective_role,
        )

    return {
        "success": True,
        "schema_path": str(saved_path),
        "config_updated": update_config,
        "config_file": str(cfg_path) if cfg_path else None,
        "role": effective_role,
        "message": "Initial schema saved. Restart the MCP server to load it.",
    }


# ---------------------------------------------------------------------------
# Bundled preset support
# ---------------------------------------------------------------------------


def _list_presets_raw() -> list[dict[str, str]]:
    """Return raw preset metadata (name + absolute path).

    Used internally so the slightly more decorated public functions can build
    on a single source of truth.  Returns [] if the bundled directory is
    missing (e.g. unusual install layout) rather than raising.
    """
    schema_dir = default_schema_dir()
    if not schema_dir.exists():
        return []

    presets: list[dict[str, str]] = []
    for path in sorted(schema_dir.glob("*.toml")):
        presets.append({"name": path.stem, "path": str(path.resolve())})
    return presets


def list_preset_schemas() -> dict[str, Any]:
    """List bundled preset schemas with a short description for each.

    Reads the ``[meta]`` block of each preset so the description shown to the
    user is taken directly from the schema file rather than duplicated here.
    """
    raw_presets = _list_presets_raw()
    presets: list[dict[str, Any]] = []

    for preset in raw_presets:
        meta = _read_preset_meta(Path(preset["path"]))
        presets.append(
            {
                "name": preset["name"],
                "path": preset["path"],
                "description": meta.get("description", ""),
                "version": meta.get("version", ""),
                "schema_name": meta.get("name", preset["name"]),
            }
        )

    return {
        "success": True,
        "schema_dir": str(default_schema_dir()),
        "preset_count": len(presets),
        "presets": presets,
    }


def _read_preset_meta(path: Path) -> dict[str, str]:
    """Parse only the ``[meta]`` table of a preset schema.

    Tolerant: returns an empty dict on any parse error so listing never
    fails because one file is malformed.
    """
    try:
        import sys

        if sys.version_info >= (3, 11):
            import tomllib
        else:
            import tomli as tomllib  # type: ignore[no-redef]
        with open(path, "rb") as f:
            data = tomllib.load(f)
        meta = data.get("meta", {})
        return {k: str(v) for k, v in meta.items() if isinstance(v, (str, int, float))}
    except Exception:  # noqa: BLE001
        return {}


def use_preset_schema(
    preset_name: str,
    taxonomy_path: str | None = None,
    output_path: str | None = None,
    role: str | None = None,
    copy: bool = False,
    overwrite: bool = False,
    update_config: bool = True,
) -> dict[str, Any]:
    """Wire a bundled preset into the user's ``config.toml``.

    By default this writes ``[server].schema = <preset_name>`` and clears any
    previous ``schema_path`` override.  This is the simplest, most stable
    integration: the user keeps using the bundled, version-controlled preset
    file.

    Set ``copy=True`` to instead copy the preset into ``output_path`` (or the
    default user config dir) and point ``schema_path`` at the copy.  Use this
    when the user wants a personal copy they can edit without touching the
    package install.

    Refuses to overwrite an existing target file when ``copy=True`` unless
    ``overwrite=True``.

    ``role`` is validated against :class:`Role`.  When ``update_config`` is
    True and no ``role`` is provided, the persisted config defaults to
    ``CONTRIBUTOR`` so that ``ServerConfig.explicit_role_configured`` becomes
    True on the next load and the server leaves onboarding mode.
    """
    raw_presets = _list_presets_raw()
    by_name = {p["name"]: p for p in raw_presets}
    if preset_name not in by_name:
        return {
            "error": True,
            "message": (
                f"Unknown preset '{preset_name}'. Available: " + ", ".join(sorted(by_name.keys()))
            ),
            "available_presets": sorted(by_name.keys()),
        }

    effective_role: str | None = None
    if update_config:
        candidate = role if role else Role.CONTRIBUTOR
        try:
            effective_role = Role.validate(candidate)
        except ValueError as exc:
            return {"error": True, "message": str(exc)}

    preset_path = Path(by_name[preset_name]["path"])

    saved_path: Path | None = None
    if copy:
        target = Path(output_path).expanduser() if output_path else _config_dir() / preset_path.name
        if target.exists() and not overwrite:
            return {
                "error": True,
                "message": (
                    f"Target file already exists: {target}. Pass overwrite=true to replace it."
                ),
            }
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(preset_path, target)
        saved_path = target.resolve()

    cfg_path: Path | None = None
    if update_config:
        cfg_path = upsert_server_config(
            schema_path=str(saved_path) if saved_path else None,
            schema_name=preset_name if not saved_path else None,
            taxonomy_path=str(Path(taxonomy_path).expanduser().resolve())
            if taxonomy_path
            else None,
            role=effective_role,
            clear_schema_path=not saved_path,
        )

    return {
        "success": True,
        "preset_name": preset_name,
        "preset_path": str(preset_path.resolve()),
        "copied_to": str(saved_path) if saved_path else None,
        "config_updated": update_config,
        "config_file": str(cfg_path) if cfg_path else None,
        "role": effective_role,
        "message": (f"Preset '{preset_name}' selected. Restart the MCP server to load it."),
    }


# ---------------------------------------------------------------------------
# Config upsert (single implementation, reused by CLI and MCP)
# ---------------------------------------------------------------------------


def upsert_server_config(
    schema_path: str | None = None,
    schema_name: str | None = None,
    taxonomy_path: str | None = None,
    role: str | None = None,
    clear_schema_path: bool = False,
) -> Path:
    """Insert/update ``[server]`` keys in the user config file.

    Behaviour:

    - ``schema_path``:  if provided, set ``schema_path = "<value>"``.
    - ``schema_name``:  if provided, set ``schema = "<value>"`` (preset selection).
    - ``taxonomy_path``: if provided, set ``taxonomy_path = "<value>"``.
    - ``role``:         if provided, set ``role = "<value>"``. Validated against
      :class:`Role`. Persisting an explicit role is what flips
      ``ServerConfig.explicit_role_configured`` to ``True`` on next load, which
      is required for the server to leave onboarding mode.
    - ``clear_schema_path``: if True, comment out an existing ``schema_path``
      line.  Useful when switching from a generated schema back to a named
      preset.

    The function preserves comments and ordering as much as possible by
    operating on raw lines rather than re-emitting parsed TOML.  This is the
    single implementation; the CLI wizard calls into it.
    """
    validated_role: str | None = Role.validate(role) if role else None

    cfg_path = default_config_path()
    cfg_path.parent.mkdir(parents=True, exist_ok=True)

    lines = cfg_path.read_text(encoding="utf-8").splitlines() if cfg_path.exists() else []
    new_lines: list[str] = []
    in_server = False
    saw_server = False
    wrote_schema_path = False
    wrote_schema_name = False
    wrote_taxonomy = False
    wrote_role = False

    def append_missing_server_keys() -> None:
        nonlocal wrote_schema_path, wrote_schema_name, wrote_taxonomy, wrote_role
        # Role first so the file reads "role = ... ; schema = ..." top-down.
        if validated_role and not wrote_role:
            new_lines.append(f'role = "{validated_role}"')
            wrote_role = True
        if schema_path and not wrote_schema_path:
            new_lines.append(f'schema_path = "{schema_path}"')
            wrote_schema_path = True
        if schema_name and not wrote_schema_name:
            new_lines.append(f'schema = "{schema_name}"')
            wrote_schema_name = True
        if taxonomy_path and not wrote_taxonomy:
            new_lines.append(f'taxonomy_path = "{taxonomy_path}"')
            wrote_taxonomy = True

    for line in lines:
        stripped = line.strip()
        if stripped == "[server]":
            saw_server = True
            in_server = True
            new_lines.append(line)
            continue

        if stripped.startswith("[") and stripped != "[server]":
            if in_server:
                append_missing_server_keys()
            in_server = False
            new_lines.append(line)
            continue

        if in_server and (stripped.startswith("role ") or stripped.startswith("role=")):
            if validated_role:
                new_lines.append(f'role = "{validated_role}"')
                wrote_role = True
                continue
            new_lines.append(line)
            continue

        if in_server and stripped.startswith("schema_path"):
            if schema_path:
                new_lines.append(f'schema_path = "{schema_path}"')
                wrote_schema_path = True
                continue
            if clear_schema_path:
                new_lines.append(f"# {stripped}  # cleared by preset selection")
                continue
            # leave untouched
            new_lines.append(line)
            continue

        if in_server and (stripped.startswith("schema ") or stripped.startswith("schema=")):
            if schema_name:
                new_lines.append(f'schema = "{schema_name}"')
                wrote_schema_name = True
                continue
            if schema_path:
                # generated schema overrides named schema
                new_lines.append(f"# {stripped}  # overridden by schema_path")
                continue
            new_lines.append(line)
            continue

        if in_server and stripped.startswith("taxonomy_path"):
            if taxonomy_path:
                new_lines.append(f'taxonomy_path = "{taxonomy_path}"')
                wrote_taxonomy = True
                continue
            new_lines.append(line)
            continue

        new_lines.append(line)

    if not saw_server:
        if new_lines and new_lines[-1].strip():
            new_lines.append("")
        new_lines.append("[server]")
        in_server = True

    if in_server:
        append_missing_server_keys()

    cfg_path.write_text("\n".join(new_lines) + "\n", encoding="utf-8")
    return cfg_path


# ---------------------------------------------------------------------------
# Post-onboarding reconfiguration (ADR 17)
#
# These functions back the runtime reconfigure_* MCP tools registered at
# CONTRIBUTOR level in server.py.  They are intentionally one-way: schema /
# taxonomy mutation is allowed at any role, role downgrade is allowed, role
# upgrade via MCP is forbidden by design.  See ADR 17 for the threat model.
# ---------------------------------------------------------------------------


_ROLE_ELEVATION_FORBIDDEN_CODE = "role_elevation_forbidden"


def reconfigure_active_schema(
    schema_name: str | None = None,
    schema_path: str | None = None,
    dry_run: bool = False,
) -> dict[str, Any]:
    """Switch the active schema by updating ``config.toml``.

    Exactly one of ``schema_name`` (a bundled preset) or ``schema_path``
    (a file path to a custom schema TOML) must be provided.

    When ``dry_run=True``: validate all inputs (preset name exists, schema
    file exists, etc.) and return a preview describing what *would* be
    written, but do not touch ``config.toml``.  Returns ``code="dry_run"``
    per ADR 14.

    Does not mutate Taskwarrior tasks.  Server restart required to apply
    (runtime reload is not yet implemented).
    """
    if not schema_name and not schema_path:
        return {
            "error": True,
            "message": "Provide exactly one of schema_name or schema_path.",
        }
    if schema_name and schema_path:
        return {
            "error": True,
            "message": (
                "Provide exactly one of schema_name or schema_path, not both. "
                "schema_path overrides schema_name when both are set in "
                "config.toml; pass only the one you intend to activate."
            ),
        }

    if schema_name:
        known = {p["name"] for p in _list_presets_raw()}
        if schema_name not in known:
            return {
                "error": True,
                "message": (
                    f"Unknown preset '{schema_name}'. "
                    f"Available: {sorted(known)}"
                ),
                "available_presets": sorted(known),
            }
        if dry_run:
            return {
                "success": True,
                "code": "dry_run",
                "schema_name": schema_name,
                "schema_path": None,
                "restart_required": True,
                "preview": {
                    "would_write": {"schema": schema_name},
                    "would_clear": "schema_path",
                },
                "message": (
                    f"DRY RUN: would set [server].schema = '{schema_name}' "
                    "and clear any existing schema_path. No file written."
                ),
            }
        cfg_path = upsert_server_config(
            schema_name=schema_name,
            clear_schema_path=True,
        )
        return {
            "success": True,
            "schema_name": schema_name,
            "schema_path": None,
            "config_file": str(cfg_path),
            "restart_required": True,
            "message": (
                f"Schema set to preset '{schema_name}'. "
                "Restart the MCP server to load it."
            ),
        }

    # schema_path branch
    resolved = Path(schema_path).expanduser().resolve()
    if not resolved.exists():
        return {
            "error": True,
            "message": f"Schema file not found: {resolved}",
        }
    if dry_run:
        return {
            "success": True,
            "code": "dry_run",
            "schema_name": None,
            "schema_path": str(resolved),
            "restart_required": True,
            "preview": {"would_write": {"schema_path": str(resolved)}},
            "message": (
                f"DRY RUN: would set [server].schema_path = '{resolved}'. "
                "No file written."
            ),
        }
    cfg_path = upsert_server_config(schema_path=str(resolved))
    return {
        "success": True,
        "schema_name": None,
        "schema_path": str(resolved),
        "config_file": str(cfg_path),
        "restart_required": True,
        "message": (
            f"Schema path set to {resolved}. Restart the MCP server to load it."
        ),
    }


def reconfigure_taxonomy_path(path: str, dry_run: bool = False) -> dict[str, Any]:
    """Update the ``taxonomy_path`` entry in ``config.toml``.

    Validates that the target file exists before persisting.  The taxonomy
    file influences how the model interprets task semantics; pointing it at
    a non-existent path would silently disable taxonomy awareness.

    When ``dry_run=True``: run all validation, return a preview, but do not
    write ``config.toml``.  Returns ``code="dry_run"`` per ADR 14.
    """
    if not path or not path.strip():
        return {"error": True, "message": "path must be a non-empty string."}

    resolved = Path(path).expanduser().resolve()
    if not resolved.exists():
        return {
            "error": True,
            "message": f"Taxonomy file not found: {resolved}",
        }
    if not resolved.is_file():
        return {
            "error": True,
            "message": f"Taxonomy path is not a regular file: {resolved}",
        }

    if dry_run:
        return {
            "success": True,
            "code": "dry_run",
            "taxonomy_path": str(resolved),
            "restart_required": True,
            "preview": {"would_write": {"taxonomy_path": str(resolved)}},
            "message": (
                f"DRY RUN: would set [server].taxonomy_path = '{resolved}'. "
                "No file written."
            ),
        }

    cfg_path = upsert_server_config(taxonomy_path=str(resolved))
    return {
        "success": True,
        "taxonomy_path": str(resolved),
        "config_file": str(cfg_path),
        "restart_required": True,
        "message": (
            f"Taxonomy path set to {resolved}. Restart the MCP server to "
            "load it."
        ),
    }


def reconfigure_role(
    current_role: str,
    target_role: str,
    dry_run: bool = False,
) -> dict[str, Any]:
    """Change the persisted role — downgrade only.

    Refuses if ``level(target) > level(current)``.  Self-elevation via MCP
    is forbidden by design (ADR 17); the structured error includes the
    ``role_elevation_forbidden`` code so dashboards / SIEM queries can
    surface attempts.

    A no-op (target == current) succeeds and returns ``success=True`` so
    the tool is idempotent for clients that re-issue on transient failures.

    When ``dry_run=True``: run all validation (including the elevation
    refusal check) and return a preview, but do not write ``config.toml``.
    Returns ``code="dry_run"`` on success per ADR 14.  Refusal-class
    errors (role_elevation_forbidden) trigger regardless of dry_run — a
    forbidden elevation is forbidden whether or not the LLM was just
    "asking".
    """
    try:
        target = Role.validate(target_role)
    except ValueError as exc:
        return {"error": True, "message": str(exc)}

    try:
        current_validated = Role.validate(current_role)
    except ValueError as exc:
        return {
            "error": True,
            "message": f"Current role is invalid: {exc}",
        }

    if Role.level(target) > Role.level(current_validated):
        return {
            "error": True,
            "error_code": _ROLE_ELEVATION_FORBIDDEN_CODE,
            "current_role": current_validated,
            "requested_role": target,
            "message": (
                f"Self-elevation forbidden: cannot raise role from "
                f"{current_validated} to {target} via MCP (ADR 17). "
                "To elevate, run './dev.sh init --role <ROLE>' from a "
                "shell, or hand-edit ~/.config/taskchampion-mcp/config.toml "
                "and restart the MCP server."
            ),
        }

    if dry_run:
        return {
            "success": True,
            "code": "dry_run",
            "previous_role": current_validated,
            "new_role": target,
            "restart_required": True,
            "preview": {"would_write": {"role": target}},
            "message": (
                f"DRY RUN: would set [server].role = '{target}' "
                f"(downgrade from {current_validated}). No file written."
            ),
        }

    cfg_path = upsert_server_config(role=target)
    return {
        "success": True,
        "previous_role": current_validated,
        "new_role": target,
        "config_file": str(cfg_path),
        "restart_required": True,
        "message": (
            f"Role set to {target} (from {current_validated}). "
            "Restart the MCP server to apply."
        ),
    }


